practice.solution:
n = int(input())
phases = ['Ask', 'Prepare', 'Process', 'Analyze', 'Share', 'Act']
groups = {p: [] for p in phases}
unknown = 0

for _ in range(n):
    phase, _, task = input().partition('|')
    phase = phase.strip().capitalize()
    if phase == 'Analyse':
        phase = 'Analyze'
    task = task.strip()
    if phase in groups and task:
        groups[phase].append(task)
    else:
        unknown += 1

printed = False
for p in phases:
    if groups[p]:
        print(p + ': ' + '; '.join(groups[p]))
        printed = True
if not printed:
    print('No tasks')
if unknown:
    print(f'Unrecognised: {unknown}')
